-- Regras do motor versionadas na base. Não altera dados de clientes, transações ou políticas de peso.

CREATE TABLE risk_engine_rule (
    id             BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    organization_id BIGINT       NOT NULL DEFAULT 1,
    rule_key       VARCHAR(16)  NOT NULL,
    display_key    VARCHAR(16)  NOT NULL,
    name           VARCHAR(160) NOT NULL,
    summary        VARCHAR(500),
    priority       INTEGER      NOT NULL,
    status         VARCHAR(20)  NOT NULL,
    kind           VARCHAR(64)  NOT NULL,
    params_json    TEXT         NOT NULL DEFAULT '{}',
    outcome        VARCHAR(32)  NOT NULL,
    version        INTEGER      NOT NULL DEFAULT 1,
    builtin        BOOLEAN      NOT NULL DEFAULT FALSE,
    note           VARCHAR(500),
    created_by     VARCHAR(160) NOT NULL,
    created_at     TIMESTAMP    NOT NULL,
    published_by   VARCHAR(160),
    published_at   TIMESTAMP
);
CREATE UNIQUE INDEX ux_engine_rule_ver ON risk_engine_rule(organization_id, rule_key, version);
CREATE INDEX ix_engine_rule_status ON risk_engine_rule(organization_id, status, priority);

CREATE TABLE risk_engine_rule_event (
    id       BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    rule_id  BIGINT       NOT NULL REFERENCES risk_engine_rule(id),
    action   VARCHAR(30)  NOT NULL,
    actor    VARCHAR(160) NOT NULL,
    detail   VARCHAR(500),
    at       TIMESTAMP    NOT NULL
);

